      "speaker": "bot",
      "text": "Hello दशरथी जी आपको कौन सा product चाहिए please details बता दीजिए।"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "के house के लिए एक generator चाहिए।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आपको जो बिजली जाने पर backup के लिए इस्तेमाल होता है वही चाहिए ना?"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "confirm कर दें।"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "हाँ हाँ हाँ हाँ।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "कितना ये आता है?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "कितना voltage देगा?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "उसके बारे में थोड़ा बताओ।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "हमारे पास अलग-अलग options हैं।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "पहले बताइए आपको कितनी क्षमता वाला चाहिए जैसे 15 kg या 25 kg या कुछ और?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "नहीं home के लिए छोटा वाला चाहिए ज्यादा नहीं है।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "समझ गई आपके घर के लिए छोटा वाला चाहिए।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "बताइए आपको किस तरह का चाहिए?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "silent या non-silent?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "ये silent वाला।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
